 const directAssets=assets.filter(asset=>!embedUrl(asset.mediaUrl));const embed=video.permalink?embedUrl(video.permalink):assets.map(asset=>embedUrl(asset.mediaUrl)).find(Boolean)||null;const visualAssets=directAssets.length?directAssets:embed?[]:video.thumbnailUrl?[{mediaUrl:video.thumbnailUrl,mediaType:'image'}]:[];
 const platform=String(video.platform||'VIDEO').toUpperCase();const Icon=platform==='INSTAGRAM'?Instagram:platform==='FACEBOOK'?Facebook:platform==='YOUTUBE'?Youtube:Film;const assignableId=portalApplicationVideoId(video);const applicationVideoName=video.applicationVideoName||(video.topic==='AV'?video.categoryName:'')||'';const assignKey=assignableId||`av-name:${applicationVideoName.trim().toLowerCase()}`;const canAssign=Boolean(assignableId);const originalUrl=video.permalink||window.location.href;const commentsVideoId=portalApplicationVideoId(video);
 useEffect(()=>{if(!commentsOpen)return;if(!commentsVideoId){setCommentRows([]);setCommentsError('Comments are not available because this post is missing its application video ID.');return;}let live=true;setCommentsLoading(true);setCommentsError('');void socialMedia.videoComments(commentsVideoId,0,100).then(rows=>{if(live)setCommentRows(rows)}).catch(reason=>{if(live){setCommentRows([]);setCommentsError(reason instanceof Error?reason.message:'Could not load comments.')}}).finally(()=>{if(live)setCommentsLoading(false)});return()=>{live=false}},[commentsOpen,commentsVideoId]);
 async function copyLink(){try{await navigator.clipboard.writeText(originalUrl);setNotice('Post link copied.');}catch{setNotice('Could not copy the link in this browser.');}}
 const pretty=(value:number|undefined)=>value===undefined?'N/A':new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(value);const metricStatus=[views,likes,comments,shares].some(value=>value!==undefined)?'Engagement values returned by the audience feed.':'Audience feed did not return engagement metrics.';
 return <article className="portal-video-card">
  <header className="portal-video-header"><span className={`portal-video-platform ${platform.toLowerCase()}`}><Icon size={16}/>{platform.charAt(0)+platform.slice(1).toLowerCase()}</span>{video.accountName&&<span className="portal-video-account">{video.accountName}</span>}</header>
  {visualAssets.length>0&&!playbackFailed?<div className={`portal-video-assets${visualAssets.length>1?' multiple':''}`}>{visualAssets.map((asset,index)=>isPortalVideo(asset)?<video key={`${asset.mediaUrl}-${index}`} controls playsInline preload="metadata" poster={asset.thumbnailUrl||video.thumbnailUrl} onError={()=>setPlaybackFailed(true)}><source src={asset.mediaUrl} type={asset.mimeType?.includes('/')?asset.mimeType:asset.mediaType?.includes('/')?asset.mediaType:undefined}/></video>:<img key={`${asset.mediaUrl}-${index}`} src={asset.mediaUrl} alt={video.title||'Social media post media'} loading="lazy"/>)}</div>:embed?<div className="portal-video-assets"><iframe src={embed} title={`${video.title||'Social media'} preview`} loading="lazy" allow="autoplay; encrypted-media; picture-in-picture; web-share" allowFullScreen referrerPolicy="strict-origin-when-cross-origin"/></div>:<div className="portal-video-no-media">{playbackFailed?'Video preview is unavailable. Open the original post below.':'No media preview was provided for this post.'}</div>}
  <div className="portal-video-copy"><h2>{video.title||video.movieTitle||'Audience post'}</h2>{(video.topic||video.categoryName)&&<span className="portal-video-movie">{video.topic||'CATEGORY'} · {video.categoryName||video.movieTitle||video.applicationVideoName||'Name unavailable'}</span>}{!video.categoryName&&video.movieTitle&&video.movieTitle!==video.title&&<span className="portal-video-movie">{video.movieTitle}</span>}{video.caption&&<p>{video.caption}</p>}<div className="portal-video-footer">{(video.publishedAt||video.createdAt)&&<time dateTime={video.publishedAt||video.createdAt}>{new Date(video.publishedAt||video.createdAt!).toLocaleDateString()}</time>}{video.permalink&&<a href={video.permalink} target="_blank" rel="noreferrer">View original post <ArrowUpRight size={14}/></a>}</div>
   <div className="portal-engagement-row" aria-label="Post engagement and actions"><span title="Views"><Eye size={16}/><small>{pretty(views)}</small></span><span title="Likes"><ThumbsUp size={16}/><small>{pretty(likes)}</small></span><button type="button" title="Comments" aria-expanded={commentsOpen} onClick={()=>setCommentsOpen(value=>!value)}><MessageCircle size={16}/><small>{pretty(comments)}</small></button><button type="button" className="portal-save-disabled" title="Save posts is not available: the backend has no audience save endpoint." aria-label="Saving is unavailable" disabled><Bookmark size={16}/></button><div className="portal-share-wrap"><button type="button" title="Share post" aria-label="Share post" aria-expanded={shareOpen} onClick={()=>setShareOpen(value=>!value)}><Share2 size={16}/></button>{shareOpen&&<div className="portal-share-menu"><button type="button" onClick={()=>void copyLink()}><Copy size={14}/>Copy link</button><a href={`https://wa.me/?text=${encodeURIComponent(originalUrl)}`} target="_blank" rel="noreferrer">WhatsApp</a><a href={`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(originalUrl)}`} target="_blank" rel="noreferrer">Facebook</a><a href={`https://twitter.com/intent/tweet?url=${encodeURIComponent(originalUrl)}`} target="_blank" rel="noreferrer">X</a>{typeof navigator!=='undefined'&&'share'in navigator&&<button type="button" onClick={()=>void navigator.share({url:originalUrl,title:video.title||'Audience Verdict post'}).catch(()=>undefined)}>More…</button>}</div>}</div>{onSelfAssign&&<button type="button" className="portal-assign-icon" disabled={!canAssign||selfAssigned||selfAssignBusy} title={!canAssign?'This post has no application video name or ID.':selfAssigned?'Already in My Videos':selfAssignBusy?'Adding to My Videos…':'Assign application video to My Videos'} aria-label={selfAssigned?'Post assigned':canAssign?'Assign to My Videos':'Assignment unavailable'} onClick={()=>canAssign&&onSelfAssign(video)}><UserRoundPlus size={16}/></button>}{onSelfUnassign&&<button type="button" className="portal-assign-icon" disabled={!portalApplicationVideoId(video)||selfUnassignBusy} title={selfUnassignBusy?'Removing from My Videos…':'Remove application video from My Videos'} onClick={()=>onSelfUnassign(video)}><UserRoundMinus size={16}/> Unassign</button>}</div>
   {(reach!==undefined||impressions!==undefined)&&<div className="portal-extra-metrics">{reach!==undefined&&<span>Reach {pretty(reach)}</span>}{impressions!==undefined&&<span>Impressions {pretty(impressions)}</span>}</div>}<div className="portal-metric-status">{metricStatus}</div>{commentsOpen&&<section className="portal-comments-panel" aria-label="Post comments"><header><b>Comments</b><span>{commentsLoading?'Loading…':`${commentRows.length} loaded${comments!==undefined?` · ${pretty(comments)} total`:''}`}</span></header>{commentsLoading?<p>Loading comments…</p>:commentsError?<p className="portal-comments-error">{commentsError}</p>:commentRows.length?<ul>{commentRows.map(comment=><li key={comment.id}><div className="portal-comment-heading"><strong>{comment.author_name||'Audience member'}</strong><time>{comment.published_at?new Date(comment.published_at).toLocaleString():'Date unavailable'}</time></div><p>{comment.comment_text||'Comment text unavailable'}</p><small>{comment.like_count??0} likes · {comment.reply_count??0} replies</small></li>)}</ul>:<p>No stored comments were returned for this application video.</p>}</section>}{notice&&<div className="portal-card-notice" role="status">{notice}</div>}
  </div>
 </article>;
