  const factW=venueW/2;facts.forEach(([label,value],i)=>{const col=i%2,row=Math.floor(i/2),fx=venueX+col*factW,fy=72+row*25;if(col===1)pdf.setDrawColor(...line),pdf.line(fx-5,64,fx-5,139);write(label,fx,fy,5.5,red,true,factW-8);write(value,fx,fy+7,8,i===5?red:ink,true,factW-8);});
  pdf.setDrawColor(...line);pdf.line(venueX,143,stubX-8,143);
  const statusFill:[number,number,number]=booking.status==='CONFIRMED'?[10,61,43]:[74,51,22],statusColor:[number,number,number]=booking.status==='CONFIRMED'?green:[255,191,91];pdf.setFillColor(...statusFill);pdf.roundedRect(venueX,151,28,8,4,4,'F');write(booking.status==='CONFIRMED'?'ÃƒÂ¢Ã…â€œÃ¢â‚¬Å“  CONFIRMED':booking.status,venueX+14,156.5,5,statusColor,true,26,'center');write(`Booking ID: ${booking.id}`,venueX+33,156.5,6.3,ink,true,venueW-35);
  write(`Confirmation: ${booking.confirmationStatus}${booking.attended?' Ãƒâ€šÃ‚Â· Attended':''}`,venueX+33,166,6,muted,false,venueW-35);
  write('YOUR TICKET',stubX+stubW/2,43,7,red,true,stubW-8,'center');
  const qrSize=38,qrX=stubX+(stubW-qrSize)/2,qrY=50;pdf.setFillColor(255,255,255);pdf.roundedRect(qrX-2,qrY-2,qrSize+4,qrSize+4,3,3,'F');pdf.addImage(qr,'PNG',qrX,qrY,qrSize,qrSize,undefined,'FAST');
