      <p className="ticket-movie-meta">{movie?.language||'Movie'} <span>Ãƒâ€šÃ‚Â·</span> {movie?.genre?.join(' / ')||'Cinema'} <span>Ãƒâ€šÃ‚Â·</span> {movie?.duration?`${movie.duration} min`:''}</p>
