      <p className="ticket-screen-name">{theatre?.address?`${theatre.address}, ${theatre.city}`:booking.snapshot.screen}{theatre?.city?`, ${theatre.city}`:''}{screen?` Ãƒâ€šÃ‚Â· ${screen.name}`:''}</p>
