export function Reviews(){
 const [uploads,setUploads]=useState<Upload[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [refreshKey,setRefreshKey]=useState(0);const [page,setPage]=useState(0);const [pageSize,setPageSize]=useState(6);const [commentsUpload,setCommentsUpload]=useState<Upload|null>(null);const {user}=useApp();const [assignedIds,setAssignedIds]=useState<Set<string>>(new Set());const [assigningId,setAssigningId]=useState<string|null>(null);const [assignmentNotice,setAssignmentNotice]=useState('');
 useEffect(()=>{let live=true;setLoading(true);setError('');void socialMedia.assignedUploads().then(rows=>{const inventory=rows.map(({video,upload})=>({...upload,video_id:video.id,video_title:video.title}));if(live)setUploads(inventory)}).catch(reason=>{if(live){setUploads([]);setError(reason instanceof Error?reason.message:'Could not load application video uploads.')}}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[refreshKey]);
 useEffect(()=>{if(!user?.id)return;let live=true;void socialMedia.myVideoAssignments(0,100).then(page=>{if(live)setAssignedIds(new Set(page.items.map(row=>String(row.videoId||row.video_id||row.applicationVideoId||row.application_video_id||row.video?.id||row.applicationVideo?.id||""))))}).catch(()=>undefined);return()=>{live=false}},[user?.id,refreshKey]);const selfAssign=async(upload:Upload)=>{const videoId=String(upload.video_id||"");if(!videoId||!user?.id||assigningId)return;setAssigningId(videoId);setAssignmentNotice("");try{await socialMedia.selfAssign([videoId]);setAssignedIds(current=>new Set([...current,videoId]));setAssignmentNotice(`${upload.video_title||"Application video"} added to My Videos.`)}catch(reason){setAssignmentNotice(reason instanceof Error?reason.message:"Could not assign this video.")}finally{setAssigningId(null)}};const toPortalVideo=(upload:Upload):PortalVideo=>{const row=upload as Upload&Record<string,any>;const rawAssets=Array.isArray(row.assets)?row.assets:[];const assets:PortalVideoAsset[]=rawAssets.map((asset:Record<string,any>)=>{const mediaUrl=String(asset.mediaUrl||asset.media_url||asset.url||asset.src||'');return mediaUrl?{...asset,mediaUrl,thumbnailUrl:asset.thumbnailUrl||asset.thumbnail_url}:null}).filter((asset:any)=>Boolean(asset)) as PortalVideoAsset[];const directMedia=String(row.mediaUrl||row.media_url||row.video_url||row.videoUrl||'');if(directMedia&&!assets.some(asset=>asset.mediaUrl===directMedia))assets.unshift({mediaUrl:directMedia,mediaType:String(row.mediaType||row.media_type||row.mimeType||'')||undefined});let metadata:unknown=row.engagement_metadata;if(typeof metadata==='string'){try{metadata=JSON.parse(metadata)}catch{}}
  return {id:upload.id,platform:upload.platform,title:upload.title||upload.video_title||'Social post',caption:String(row.caption||row.description||''),accountName:String(row.account_name||''),accountId:upload.account_id,permalink:upload.permalink,thumbnailUrl:String(row.thumbnailUrl||row.thumbnail_url||'')||undefined,assets,applicationVideoId:String(upload.video_id||''),applicationVideoName:upload.video_title||'',createdAt:upload.retrieved_at,publishedAt:String(row.published_at||row.publishedAt||''),views:row.views??row.view_count??row.viewCount,likes:row.likes??row.like_count??row.likeCount,comments:row.comments??row.comment_count??row.commentCount,shares:row.shares??row.share_count??row.shareCount,engagement_metadata:metadata as PortalVideo['engagement_metadata']};};
 const groups=Array.from(uploads.reduce((map,upload)=>{const key=upload.video_id?`video:${upload.video_id}`:`upload:${upload.id}`;const rows=map.get(key)||[];rows.push(upload);map.set(key,rows);return map},new Map<string,Upload[]>()).entries()).map(([key,rows])=>({key,uploads:rows}));const pageCount=Math.max(1,Math.ceil(groups.length/pageSize));const pageItems=groups.slice(page*pageSize,(page+1)*pageSize);const inventoryMetric=(upload:Upload,kind:PortalMetric)=>getPortalMetric(toPortalVideo(upload),kind);const metricTotal=(kind:PortalMetric)=>{const values=uploads.map(upload=>inventoryMetric(upload,kind)).filter((value):value is number=>value!==undefined);return values.length?new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(values.reduce((sum,value)=>sum+value,0)):'N/A'};
 return <main className="social-reviews-page reviews-inventory-page"><section className="reviews-hero" style={{backgroundImage:`linear-gradient(90deg,#080b0dea 0%,#080b0dbb 39%,#080b0d22 77%),linear-gradient(0deg,#080b0d99 0%,transparent 42%),url("${reviewsHeroImage}")`}}><div className="reviews-hero-inner"><span className="reviews-eyebrow">AUDIENCE VERDICT · SOCIAL MEDIA</span><h1>Social post inventory<span>.</span></h1><p>Every social post from the administrator upload inventory.</p></div></section><div className="social-reviews-content"><header className="reviews-inventory-heading"><div><h2>All inventory posts</h2><p>{uploads.length} posts across all connected platforms</p></div><button type="button" className="portal-refresh-button" disabled={loading} onClick={()=>setRefreshKey(value=>value+1)}><RefreshCw size={16}/>Refresh</button></header><section className="social-reviews-stats reviews-inventory-stats" aria-label="Inventory engagement summary"><div className="reviews-stat"><Play/><strong>{uploads.length.toLocaleString()}</strong><span>Total videos</span></div><div className="reviews-stat"><Eye/><strong>{metricTotal('views')}</strong><span>Views</span></div><div className="reviews-stat"><ThumbsUp/><strong>{metricTotal('likes')}</strong><span>Likes</span></div><div className="reviews-stat"><MessageCircle/><strong>{metricTotal('comments')}</strong><span>Comments</span></div><div className="reviews-stat"><Share2/><strong>{metricTotal('shares')}</strong><span>Shares</span></div></section>{loading?<section className="portal-videos-state" role="status">Loading inventory posts…</section>:error?<section className="portal-videos-state error"><h2>Inventory posts could not be loaded.</h2><p>{error}</p><button className="button secondary" onClick={()=>setRefreshKey(value=>value+1)}><RefreshCw size={15}/>Try again</button></section>:uploads.length?<><p className="social-reviews-count">Showing {pageItems.reduce((total,group)=>total+group.uploads.length,0)} of {uploads.length} posts · Page {page+1} of {pageCount}</p><div className="social-video-groups reviews-inventory-grid">{pageItems.map(group=><ApplicationVideoInventoryCard key={group.key} uploads={group.uploads} accounts={[]} selected={false} metric={inventoryMetric} metricMessage="" onSelect={()=>undefined} onComments={setCommentsUpload} onActive={()=>undefined} reviewActions onSelfAssign={selfAssign} assignedIds={assignedIds} assigningId={assigningId}/>)}</div><nav className="portal-pagination reviews-pager" aria-label="Inventory pages"><span className="reviews-pager-count">Showing {groups.slice(0,page*pageSize).reduce((total,group)=>total+group.uploads.length,0)+1}–{groups.slice(0,(page+1)*pageSize).reduce((total,group)=>total+group.uploads.length,0)} of {uploads.length} posts</span><div className="reviews-page-buttons"><button type="button" className="button secondary small" aria-label="Previous page" disabled={page===0} onClick={()=>setPage(value=>Math.max(0,value-1))}><ChevronLeft size={16}/></button><span>{page+1} / {pageCount}</span><button type="button" className="button secondary small" aria-label="Next page" disabled={page+1>=pageCount} onClick={()=>setPage(value=>Math.min(pageCount-1,value+1))}><ChevronRight size={16}/></button></div><label className="reviews-page-size">Videos per page<select value={pageSize} onChange={event=>{setPageSize(Number(event.target.value));setPage(0)}}><option value={6}>6</option><option value={9}>9</option><option value={12}>12</option><option value={18}>18</option></select></label></nav></>:<section className="social-reviews-empty"><h2>No posts in the inventory.</h2><p>Posts imported by the administrator will appear here.</p></section>}</div>{commentsUpload&&<UploadCommentsDrawer upload={commentsUpload} accountName={String((commentsUpload as Upload&Record<string,any>).account_name||commentsUpload.video_title||commentsUpload.platform)} onClose={()=>setCommentsUpload(null)} metrics={{views:inventoryMetric(commentsUpload,"views"),likes:inventoryMetric(commentsUpload,"likes"),comments:inventoryMetric(commentsUpload,"comments"),shares:inventoryMetric(commentsUpload,"shares")}} readOnly/>}</main>;
}export function MyWaitingList(){
 const {data,user}=useApp();
 const [entries,setEntries]=useState<any[]>([]);
 const [bookings,setBookings]=useState<any[]>([]);
 const [offers,setOffers]=useState<Record<string,any>>({});
 const [busy,setBusy]=useState(true);
 const [error,setError]=useState('');
 const load=async()=>{
  setBusy(true);
  try{
   const [waiting,remoteBookings]=await Promise.all([getWaitingList(),getMyBookings().catch(()=>[])]);
   setEntries(waiting);
   const activeEntries=waiting.filter((entry:any)=>['WAITING','OFFERED'].includes(String(entry.status).toUpperCase()));
   const showIds=[...new Set(activeEntries.map((entry:any)=>String(entry.showId)))];
   const availableCounts=await Promise.all(showIds.map(async showId=>[showId,await getAvailableSeatCount(showId)] as const));
   const offersByShow=new Map<string,any>();
   for(const [showId,count] of availableCounts)if(count>0)offersByShow.set(showId,{status:'ACTIVE',remainingSeatCount:count});
   setOffers(Object.fromEntries(offersByShow));
   const localBookings=data.bookings.filter(booking=>booking.userId===user?.id);
   setBookings([...localBookings,...remoteBookings.filter(booking=>!localBookings.some(local=>local.id===booking.id))]);
   setError('');
  }catch(e){setError((e as Error).message);}
  finally{setBusy(false);}
 };
 useEffect(()=>{void load();const timer=window.setInterval(()=>void load(),10000);return()=>window.clearInterval(timer);},[user?.id]);
 const cancel=async(id:string)=>{try{await leaveWaitingList(id);await load();}catch(e){setError((e as Error).message);}};
 return <div className="container page my-waitlist-page"><SectionHeading eyebrow="YOUR SHOWS" title="My waiting list" description="We email you when seats open. Available seats can be booked by anyone through the normal seat layout."/>{error&&<Notice error>{error}</Notice>}{busy?<p className="muted">Loading your waiting-list tickets...</p>:!entries.length?<Empty title="You havenÃ¢â‚¬â„¢t joined a waiting list yet."><Link className="button" to="/movies">Find a movie</Link></Empty>:<div className="bookings-list">{entries.map(entry=>{
  const show=data.shows.find(item=>item.id===entry.showId);
  const movie=data.movies.find(item=>item.id===show?.movieId);
  const theatre=data.theatres.find(item=>item.id===show?.theatreId);
  const related=bookings.filter(booking=>booking.status!=='CANCELLED'&&booking.status!=='EXPIRED'&&(booking.waitingListEntryId===entry.id||(booking.showId===entry.showId&&(!entry.createdAt||!booking.createdAt||booking.createdAt>=entry.createdAt)))).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const booking=related[0];
  const offer=offers[entry.showId];const offeredCount=Number(offer?.remainingSeatCount)||0;const seatsAvailable=offer?.status==='ACTIVE';const status=booking?'BOOKED':seatsAvailable?'AVAILABLE':entry.status;
  const active=['WAITING','OFFERED'].includes(String(entry.status).toUpperCase())&&!booking;
  return <article className="panel booking-row waitlist-ticket" key={entry.id}>
   <div className="booking-poster">{movie?<Poster movie={movie}/>:<Ticket/>}</div>
   <div><small className="muted">WAITING LIST Ã‚Â· {entry.id.slice(0,8).toUpperCase()}</small><h3>{movie?.title||'Screening'}</h3><p className="muted">{theatre?.name||'Venue'} Ã‚Â· {show?.date||''} Ã‚Â· {show?.startTime||''}</p><p>{entry.requestedSeatsCount} {entry.requestedSeatsCount===1?'ticket':'tickets'} requested</p>
    {booking&&<div className="waitlist-booking-details"><strong>Ticket booked</strong><span>{booking.snapshot?.date||show?.date||''} Ã‚Â· {booking.snapshot?.time||show?.startTime||''}</span><span>Seats: {booking.seatIds?.join(', ')||'Seat details unavailable'}</span><span>Status: {booking.status}</span><Link className="button ticket-action" to={`/booking/${booking.id}`}><Ticket size={15}/>View details <ArrowRight size={15}/></Link></div>}
   </div>
   <div className="booking-row-status"><span className={`status ${String(status).toLowerCase()}`}>{status}</span><small className="muted">{booking?'Your ticket is available in booking details.':seatsAvailable?`${offeredCount} ${offeredCount===1?'seat is':'seats are'} currently available to everyone. Book through the normal seat layout.`:active?'You are on this show waiting list. We will email you when seats open.':entry.status==='CANCELLED'?'You left this waiting list.':entry.status==='CONVERTED'?'Booking completed.':'Waiting-list request '+String(entry.status).toLowerCase()+'.'}</small></div>
   <div className="table-actions">{seatsAvailable&&movie&&<Link className="button small" to={'/movie/'+movie.id+'/book?show='+encodeURIComponent(show?.id||'')+'&waitlistEntryId='+encodeURIComponent(entry.id)}>Book available seats <ArrowRight size={15}/></Link>}{active&&<button className="button secondary small" onClick={()=>void cancel(entry.id)}>Leave list</button>}</div>
  </article>;
 })}</div>}</div>;
}
